package com.autocare.platform.order;
import com.autocare.platform.service.MerchantActor;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class JdbcCustomerRelationsTest extends JdbcServiceWorkspaceTest {
 CustomerRelations relations;
 @BeforeEach void customers(){jdbc.update("DELETE FROM invite_registration");relations=new CustomerRelations(taskScope);jdbc.update("UPDATE `order` SET created_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 DAY) WHERE id=1");}
 com.fasterxml.jackson.databind.JsonNode listing(){return db.mapper.valueToTree(relations.list(shop,1));}
 com.fasterxml.jackson.databind.JsonNode detail(){return db.mapper.valueToTree(relations.detail(shop,1,1));}
 void order(long id,long user,long vehicle,long store,String state){jdbc.update("INSERT INTO `order`(id,order_no,user_id,vehicle_id,merchant_id,amount,pay_amount,status,created_at) VALUES(?,?,?,?,?,10,10,?,DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",id,"synthetic-customer-"+id,user,vehicle,store,state);}
 @Test void groupsOnlyOwnStoreOrdersWithStableAnchorAndNoPrivateProjection(){order(2,99,99,1,"COMPLETED");order(3,99,99,2,"PAID");order(4,99,99,1,"PENDING_PAYMENT");order(5,99,99,1,"CLOSED");var n=listing();assertEquals(1,n.path("relationships").path("total").asInt());var r=n.path("relationships").path("items").get(0);assertEquals(1,r.path("relationship_order_id").asInt());assertEquals(2,r.path("order_count").asInt());assertEquals(2,detail().path("orders").path("total").asInt());for(String k:List.of("user_id","owner_id","phone","openid","plate_no","vin","vehicle_id","order_no","amount","archives","object_key"))assertFalse((n.toString()+detail()).contains("\""+k+"\""),k);assertEquals(404,status(()->relations.detail(shop,2,1)));}
 @Test void arrivalNeedsRecordedCheckInProofNotAppointmentOrUpdatedAt(){assertTrue(detail().path("relationship").path("last_service_at").isNull());jdbc.update("UPDATE `order` SET check_in_completed_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 5 MINUTE) WHERE id=1");jdbc.update("UPDATE pickup_check SET arrived_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 10 MINUTE) WHERE order_id=1");assertTrue(detail().path("relationship").path("last_service_at").isNull());jdbc.update("INSERT INTO order_status_transition(order_id,merchant_id,from_status,to_status,action,actor_type,actor_id,occurred_at) SELECT 1,1,'PAID','RECEIVED','ORDER_CHECK_IN','staff_account',1,check_in_completed_at FROM `order` WHERE id=1");assertFalse(detail().path("relationship").path("last_service_at").isNull());assertEquals(detail().path("relationship").path("last_service_at"),detail().path("orders").path("items").get(0).path("service_at"));jdbc.update("UPDATE order_status_transition SET from_status='UNVERIFIED' WHERE action='ORDER_CHECK_IN'");assertTrue(detail().path("relationship").path("last_service_at").isNull());jdbc.update("UPDATE order_status_transition SET from_status='PAID' WHERE action='ORDER_CHECK_IN'");jdbc.update("UPDATE pickup_check SET merchant_id=2 WHERE order_id=1");assertTrue(detail().path("relationship").path("last_service_at").isNull());}
 @Test void identitySourceIsPermanentAndDoesNotInventVerifiedLegacyCustomers(){assertEquals("UNKNOWN",detail().path("relationship").path("identity_source").asText());jdbc.update("INSERT INTO invite_registration(user_id,record_id,app_id,identity_source,attribution_result,qualification_status,registered_at,rule_version) VALUES(99,?,'test-app','TEST','NONE','TEST',UTC_TIMESTAMP(),'R6A_INVITE_V1')",key());assertEquals("TEST",detail().path("relationship").path("identity_source").asText());jdbc.update("UPDATE invite_registration SET identity_source='VERIFIED_WECHAT',qualification_status='PENDING'");assertEquals("VERIFIED_WECHAT",detail().path("relationship").path("identity_source").asText());jdbc.update("UPDATE invite_registration SET rule_version='legacy'");assertEquals("UNKNOWN",detail().path("relationship").path("identity_source").asText());}
 @Test void ordinaryStaffOtherShopAndRevokedManagerCannotReadRelations(){var employee=new MerchantActor(shop.staffId(),1,"STAFF",shop.session(),shop.expires());assertEquals(403,status(()->relations.list(employee,1)));assertEquals(404,status(()->relations.detail(other,1,1)));assertEquals(0,((Map<?,?>)relations.list(other,1).get("relationships")).get("total") instanceof Number n?n.intValue():-1);jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",shop.session());assertEquals(401,status(()->relations.detail(shop,1,1)));assertEquals(401,status(()->relations.list(shop,1)));}
 @Test void deletedVehiclesMovedOwnershipDisabledOwnersAndClosedOrdersInvalidateCurrentRelation(){jdbc.update("UPDATE vehicle SET user_id=100 WHERE id=99");assertEquals(0,listing().path("relationships").path("total").asInt());assertEquals(404,status(()->relations.detail(shop,1,1)));jdbc.update("UPDATE vehicle SET user_id=99 WHERE id=99");jdbc.update("UPDATE `user` SET status=2 WHERE id=99");assertEquals(0,listing().path("relationships").path("total").asInt());jdbc.update("UPDATE `user` SET status=1 WHERE id=99");jdbc.update("UPDATE `order` SET status='CLOSED' WHERE id=1");assertEquals(404,status(()->relations.detail(shop,1,1)));}
 @Test void boundedPagingCountsCustomersSeparatelyFromTheirOrders(){for(int i=101;i<=121;i++){jdbc.update("INSERT INTO `user`(id,openid) VALUES(?,?)",i,"synthetic-customer-"+i);jdbc.update("INSERT INTO vehicle(id,user_id) VALUES(?,?)",i,i);order(i,i,i,1,"PAID");}var first=listing();assertEquals(22,first.path("relationships").path("total").asInt());assertEquals(20,first.path("relationships").path("items").size());assertEquals(2,db.mapper.valueToTree(relations.list(shop,2)).path("relationships").path("items").size());for(int i=2;i<=22;i++)order(i,99,99,1,"PAID");assertEquals(22,detail().path("orders").path("total").asInt());assertEquals(2,db.mapper.valueToTree(relations.detail(shop,1,2)).path("orders").path("items").size());assertEquals(400,status(()->relations.list(shop,0)));assertEquals(400,status(()->relations.detail(shop,0,1)));}
 @Test void relationNeverGrantsArchivesAndExistingConsentStillRevokesImmediately(){assertEquals(0,count("order_archive_grant"));assertTrue(detail().path("orders").path("items").get(0).path("service_context_available").asBoolean());assertEquals(0,context(shop).path("archives").path("total").asInt());allow();assertEquals(1,context(shop).path("archives").path("total").asInt());grants.set(owner,1,901,key(),set("REVOKED",1,null));assertEquals(0,context(shop).path("archives").path("total").asInt());assertEquals(404,status(()->grants.fileOwner(shop,1,901,601)));jdbc.update("UPDATE `order` SET status='COMPLETED' WHERE id=1");assertFalse(detail().path("orders").path("items").get(0).path("service_context_available").asBoolean());assertEquals(404,status(()->grants.context(shop,1,1)));}
 @Test void readsHaveNoWritesAndOpenDisputeRemovesArchiveEntry(){int audits=count("audit_log"),writes=count("idempotency_record");listing();detail();assertEquals(audits,count("audit_log"));assertEquals(writes,count("idempotency_record"));assertEquals(0,count("order_archive_grant"));jdbc.update("UPDATE `order` SET status='DISPUTED' WHERE id=1");assertFalse(detail().path("orders").path("items").get(0).path("service_context_available").asBoolean());assertEquals(404,status(()->grants.context(shop,1,1)));}
}
